/* ====================================================================
   PERSISTENCE (localStorage): profile/stats + settings
==================================================================== */
const LS_P='to_profile', LS_S='to_settings';
let profile=loadProfile(), settings=loadSettings();
function loadProfile(){ try{const p=JSON.parse(localStorage.getItem(LS_P)); if(p) return p;}catch(e){}
  const p={nick:'player'+Math.floor(1000+Math.random()*9000),reg:new Date().toISOString().slice(0,10),games:0,wins:0,losses:0};
  localStorage.setItem(LS_P,JSON.stringify(p)); return p; }
function saveProfile(){ localStorage.setItem(LS_P,JSON.stringify(profile)); }
function loadSettings(){ try{const s=JSON.parse(localStorage.getItem(LS_S)); if(s) return Object.assign({graphics:'medium',volume:50,lang:'en',sens:2.0},s);}catch(e){}
  return {graphics:'medium',volume:50,lang:'en',sens:2.0}; }
function saveSettings(){ localStorage.setItem(LS_S,JSON.stringify(settings)); }

